import type { Article, ArticleContentBlock, ArticleDetail, ImageAsset, Tag } from "@/types";
import { articles, getArticleById, getArticleBySlug } from "./articles";

const inlineImages = {
  leadership: { src: "/images/articles/global-leadership.png", alt: "Leaders in conversation inside a contemporary civic atrium", width: 1536, height: 1024 },
  growth: { src: "/images/articles/global-growth.png", alt: "People walking through a modern research and manufacturing campus", width: 1536, height: 1024 },
  technology: { src: "/images/articles/ai-infrastructure.png", alt: "An engineer walking through a large data center corridor", width: 1536, height: 1024 },
} satisfies Record<string, ImageAsset>;

const tag = (name: string): Tag => ({ id: `tag-${name.toLowerCase().replaceAll(" ", "-")}`, name, slug: name.toLowerCase().replaceAll(" ", "-") });
type ArticleDetailSeed = { articleId: string; tags: Tag[]; relatedArticleIds: string[]; content: ArticleContentBlock[] };

const detailSeeds: ArticleDetailSeed[] = [
  {
    articleId: "article-new-architecture-global-leadership",
    tags: [tag("Leadership"), tag("Management"), tag("Institutions"), tag("Strategy")],
    relatedArticleIds: ["article-50-leaders", "article-decisions-pressure", "article-boards-accountability"],
    content: [
      { type: "paragraph", text: "The most consequential leadership meetings now begin with an admission: the old map no longer explains the territory. Supply chains cross political boundaries, technical decisions carry social consequences, and employees expect to understand not only what an organization is doing but why its choices deserve trust. Authority still matters, but authority alone can no longer create momentum." },
      { type: "paragraph", text: "Across companies, public institutions and investment organizations, a different model is emerging. Its leaders spend less time defending a fixed center and more time building a network of capable centers. They set a direction, make the boundaries clear and give people close to the work enough context to exercise judgment. The result is not leaderless management. It is leadership distributed with intention." },
      { type: "heading", level: 2, text: "Influence Is Becoming Distributed" },
      { type: "paragraph", text: "For much of the industrial era, scale rewarded concentration. Information traveled upward, decisions moved downward and the chief executive was expected to see the whole system. That structure delivered consistency when markets moved slowly and expertise could be organized into stable functions. Today, the volume and speed of information make the same structure a source of delay." },
      { type: "paragraph", text: "The strongest organizations are responding by separating control from coherence. They do not ask every team to behave identically. They ask teams to understand a common set of priorities, operating principles and consequences. A product group in Bengaluru and a policy team in Brussels may make different choices, but both can explain how those choices advance the same institutional purpose." },
      { type: "pullQuote", quote: "Leadership is no longer defined simply by authority. It is defined by the ability to create alignment where certainty no longer exists.", attribution: "Ava Morgan" },
      { type: "paragraph", text: "This shift changes the work at the top. Senior leaders become designers of decision environments. They decide what information must be shared, which choices must remain centralized and where experimentation is worth the risk. Their influence comes from making good judgment possible at a distance rather than placing themselves inside every decision." },
      { type: "image", image: inlineImages.growth, caption: "A research campus designed to bring different disciplines into daily contact.", credit: "Illustration for The Perspective." },
      { type: "heading", level: 2, text: "The New Executive Mandate" },
      { type: "paragraph", text: "The new mandate begins with clarity. In uncertain conditions, people do not need a performance of certainty; they need an honest account of what is known, what remains unsettled and which assumptions would cause the plan to change. That discipline is more demanding than a polished forecast because it exposes the quality of the reasoning beneath it." },
      { type: "paragraph", text: "Clarity also includes saying what the organization will not pursue. A long list of priorities transfers the burden of choice downward while preserving the appearance of ambition at the top. Leaders create usable direction when they make trade-offs visible, explain the evidence behind them and give teams permission to stop work that no longer serves the central commitments." },
      { type: "callout", label: "Key takeaway", text: "Distributed leadership works only when decision rights, shared context and accountability are designed together." },
      { type: "paragraph", text: "It also requires a more expansive view of talent. Organizations once treated leadership development as a pipeline toward a small number of senior roles. The better question now is how many people can responsibly exercise leadership from their current position. That means teaching financial context to technical teams, technical context to boards and cultural context to anyone making decisions across regions." },
      { type: "bulletList", items: ["Make the few enterprise-wide priorities unmistakable.", "Place decisions with the people who hold the best current information.", "Create rapid ways to surface disagreement before it becomes failure.", "Judge leaders by the capability they build around them, not only by their personal output."] },
      { type: "heading", level: 2, text: "Institutions Are Changing" },
      { type: "paragraph", text: "Governance is changing alongside management. Boards are asking for a more direct view of culture, technology and operational resilience. Investors are looking beyond succession plans toward the depth of judgment throughout an organization. Employees are testing whether stated values survive difficult trade-offs. Each audience is asking a version of the same question: can this institution remain coherent when conditions change?" },
      { type: "paragraph", text: "The answer is visible in ordinary moments. It appears when a regional team pauses a launch because local evidence contradicts headquarters, when an executive makes the reasoning behind a reversal public, or when a board gives management time to invest in a capability whose return will not fit neatly inside the next quarter. These actions accumulate into institutional credibility." },
      { type: "paragraph", text: "That credibility is becoming an operating asset. It lowers the cost of coordination because people do not need to renegotiate the institution's intentions every time circumstances change. Teams can move faster when they trust that bad news will travel without punishment, that commitments will be applied consistently and that leaders will distinguish an honest mistake from careless judgment." },
      { type: "paragraph", text: "The same principle reaches beyond the organization. Suppliers are more willing to invest beside a company whose priorities survive leadership changes. Communities are more open to expansion when consultation begins before a decision is complete. Regulators respond differently when executives can explain not only a desired outcome but the controls, evidence and responsibilities that support it. Leadership architecture is therefore also relationship architecture." },
      { type: "divider" },
      { type: "heading", level: 2, text: "What Comes Next" },
      { type: "paragraph", text: "The next architecture of leadership will not be a universal organizational chart. It will be a set of practices that allow different structures to remain intelligent: shared context, explicit decision rights, disciplined dissent and a purpose specific enough to guide choices. Technology will make information easier to distribute, but it cannot decide which commitments deserve to endure." },
      { type: "paragraph", text: "That remains the human work of leadership. The leaders who matter most will be those who can hold a long horizon while responding to immediate facts, who can invite expertise without surrendering responsibility and who can turn a collection of talented people into an institution capable of acting together. In a fragmented world, coherence may become the rarest form of power." },
    ],
  },
  {
    articleId: "article-ai-infrastructure-race",
    tags: [tag("Artificial Intelligence"), tag("Infrastructure"), tag("Enterprise Technology"), tag("Energy")],
    relatedArticleIds: ["article-ai-infrastructure", "article-data-centers-strategic", "article-enterprise-ai-phase"],
    content: [
      { type: "paragraph", text: "The artificial-intelligence contest is moving beneath the application layer. The decisive questions are increasingly physical: who can secure power, chips, land, cooling systems, network capacity and the engineering talent required to operate them as one dependable system. Models remain visible, but infrastructure is becoming the field on which advantage is won or lost." },
      { type: "paragraph", text: "That transition is changing corporate strategy. What began as a software experiment is now entering capital plans, energy negotiations and board-level risk reviews. Enterprises that once rented modest cloud capacity are forecasting demand years ahead. Governments are treating compute as an industrial resource. Utilities are receiving requests whose scale would once have belonged to factories or entire districts." },
      { type: "heading", level: 2, text: "Compute Becomes Industrial Capacity" },
      { type: "paragraph", text: "The data center has become the AI economy's factory floor. Its output is not a physical product but the capacity to train, refine and serve models reliably. Like earlier industrial systems, it depends on a dense chain of inputs. A shortage in transformers, specialist construction labor or high-bandwidth memory can be as consequential as a breakthrough in model design." },
      { type: "paragraph", text: "This favors organizations able to coordinate across time horizons. Chip commitments may precede a product launch by years. Power agreements require a view of demand that no team can forecast precisely. Cooling designs must account for denser hardware generations that have not yet shipped. The investment case therefore depends less on a single forecast than on the ability to adapt a durable asset to multiple futures." },
      { type: "pullQuote", quote: "The next AI advantage may belong less to the company with the loudest model launch than to the one that can deliver dependable intelligence every hour of the year.", attribution: "Noor Rahman" },
      { type: "heading", level: 2, text: "Energy Moves to the Center" },
      { type: "paragraph", text: "Energy is the constraint most likely to reshape the map. Regions with abundant generation, credible grids and faster interconnection processes are attracting projects that previously clustered near established technology hubs. The result is a new geography linking data-center development with renewable generation, gas capacity, storage and, in some markets, renewed interest in nuclear power." },
      { type: "image", image: inlineImages.technology, caption: "Inside the infrastructure layer where AI systems become dependable services.", credit: "Illustration for The Perspective." },
      { type: "callout", label: "Infrastructure watch", text: "The critical bottleneck is not one component. It is the ability to coordinate chips, power, cooling, networks and software on the same schedule." },
      { type: "paragraph", text: "The environmental question cannot be separated from the economic one. Efficiency gains at the chip and model level may reduce the energy required for each task, yet lower costs can expand overall use. Responsible operators are beginning to report not only annual renewable matching but hourly consumption, local water conditions and the emissions consequences of siting decisions." },
      { type: "paragraph", text: "Communities are also becoming active participants in infrastructure decisions. A project that promises investment but competes with households for grid capacity or water will face a different standard of consent. Developers increasingly need to show how a facility strengthens local systems, whether through new transmission, recycled-water infrastructure, tax capacity or training that produces durable technical careers." },
      { type: "paragraph", text: "These negotiations reward transparency. Aggregate national commitments say little about the effect of a particular campus on a particular grid. Operators that publish regional demand profiles and explain their contingency plans give utilities and residents something concrete to assess. That openness can slow an announcement, but it may accelerate the years of dependable operation that follow." },
      { type: "heading", level: 2, text: "A More Complicated Supply Chain" },
      { type: "paragraph", text: "The supply chain extends well beyond advanced processors. Networking equipment, optical components, backup generation, switchgear and specialized maintenance all matter. The companies building resilient capacity are qualifying alternatives, standardizing designs where possible and preserving flexibility in the places where technology is moving fastest." },
      { type: "paragraph", text: "Financing adds another layer of discipline. The useful life of a building, power connection or cooling plant is longer than the commercial life of a particular accelerator. Investors therefore need to separate durable infrastructure from technology that may turn over quickly. Modular design and credible reuse plans can keep a facility valuable even as the hardware inside it changes." },
      { type: "paragraph", text: "Enterprise buyers have their own version of this problem. Reserving too little capacity can constrain a product at the moment demand becomes real; reserving too much can burden the business with expensive idle resources. Leading teams are creating portfolios of workloads, matching each one to an appropriate performance tier and revisiting those assumptions as models become more efficient." },
      { type: "paragraph", text: "This creates a premium on measurement. Utilization, latency, energy intensity and failure recovery need to be visible in the same operating view. Without that connection, finance sees cost, engineers see performance and sustainability teams see consumption, but no one sees the quality of the system as a whole. Shared measures turn infrastructure from a collection of assets into a managed capability." },
      { type: "numberedList", items: ["Secure a credible power path before announcing headline capacity.", "Design facilities for changing rack density and cooling requirements.", "Treat software orchestration as part of the physical asset, not an afterthought.", "Measure resilience and environmental impact at the regional level."] },
      { type: "heading", level: 2, text: "From Race to Operating Discipline" },
      { type: "paragraph", text: "The language of a race can obscure the endurance required. Infrastructure creates advantage only when it is used well. Idle capacity destroys returns; overstretched capacity weakens products. The mature operators will match demand to supply, route workloads intelligently and decide which models genuinely require the most expensive resources." },
      { type: "paragraph", text: "AI infrastructure is therefore not merely a technology investment. It is an operating system for a new class of enterprise capability. The organizations that approach it with industrial discipline—balancing speed with resilience, ambition with utilization and scale with public legitimacy—will define what the next phase of intelligence can reliably become." },
    ],
  },
  {
    articleId: "article-global-companies-reassess",
    tags: [tag("Global Business"), tag("Capital Investment"), tag("Manufacturing"), tag("Resilience")],
    relatedArticleIds: ["article-manufacturers-invest", "article-companies-growth-cycle", "article-industrial-strategy"],
    content: [
      { type: "paragraph", text: "Global companies are revising expansion plans as a new investment cycle gathers force across manufacturing, automation and digital infrastructure. The change is not a simple return to capacity building. Executives are directing capital toward systems that can absorb disruption, shorten critical supply chains and make production more responsive to regional demand." },
      { type: "paragraph", text: "Board discussions that once separated growth from resilience increasingly treat them as the same agenda. A plant with flexible tooling, reliable energy and multiple supplier options may cost more at the outset, but it can protect revenue when trade rules, transport routes or customer expectations shift. The premium on optionality is becoming part of the growth calculation." },
      { type: "heading", level: 2, text: "Investment Returns to the Operating Core" },
      { type: "paragraph", text: "For much of the last decade, many companies concentrated investment in software, acquisitions and asset-light expansion. Physical operations were optimized for efficiency and predictable flows. Recent shocks exposed how little room those systems contained. The response is visible in new facilities, upgraded logistics networks and long-term agreements for components previously bought on demand." },
      { type: "paragraph", text: "The strongest spending is concentrated where several priorities overlap. Advanced manufacturing projects often combine automation with lower energy use. Distribution centers are becoming data-rich coordination points. Research campuses place engineers closer to production teams so that product and process design can change together." },
      { type: "callout", label: "Newsroom note", text: "This article was updated at 1:42 PM on August 7, 2026, to include additional detail on regional investment priorities." },
      { type: "heading", level: 2, text: "Regional Networks Replace a Single Global Model" },
      { type: "paragraph", text: "The emerging pattern is not wholesale retreat from globalization. It is a move from one tightly integrated network toward several connected regional systems. Companies still want global scale, but they are less willing to depend on one route, one regulatory regime or one production cluster for critical inputs." },
      { type: "image", image: inlineImages.growth, caption: "A new investment cycle links research, production and regional supply networks.", credit: "Illustration for The Perspective." },
      { type: "pullQuote", quote: "Resilience is no longer an insurance line beside the strategy. In many industries, resilience is the strategy.", attribution: "Julian Cross" },
      { type: "paragraph", text: "This regionalization changes what companies need from leaders. Country teams require greater authority to adapt sourcing and pricing. Finance functions need measures that recognize avoided disruption, not only immediate utilization. Procurement leaders are being asked to understand geopolitics and technology road maps alongside cost." },
      { type: "paragraph", text: "It also changes the role of headquarters. The center can no longer prescribe every operating answer, but it must maintain a clear view of dependencies across the whole network. That requires common data definitions, regular stress tests and escalation rules that allow a local issue to become an enterprise decision before the cost of response rises." },
      { type: "paragraph", text: "Several companies are creating regional investment councils that bring operations, finance, policy and technology leaders into the same review. Their purpose is not to add another approval layer. It is to compare projects against shared constraints: grid access, supplier concentration, workforce availability and the strategic value of learning that can travel to other sites." },
      { type: "heading", level: 2, text: "The Discipline Behind the Headlines" },
      { type: "paragraph", text: "Announcing investment is easier than executing it. Large projects face shortages of skilled labor, equipment delays and complex permitting. Higher financing costs make sequencing more important. Companies that advance every proposal at once risk converting a strategic opportunity into an operational bottleneck." },
      { type: "paragraph", text: "Execution quality will determine whether the cycle produces enduring productivity or a collection of expensive announcements. The best programs establish a small number of repeatable designs, retain local flexibility where it matters and make operating teams responsible early enough to influence construction. A facility should not be handed from a project organization to its future operators as if the two were separate worlds." },
      { type: "paragraph", text: "Workforce planning is equally important. Automation changes the mix of skills but rarely eliminates the need for deep process knowledge. Companies are partnering with technical institutes, creating conversion programs for experienced workers and treating maintenance capability as strategic. Equipment can be purchased; the judgment required to keep a complex system reliable develops through practice." },
      { type: "paragraph", text: "Local legitimacy can become a schedule advantage. Projects move more predictably when companies engage communities around transport, housing, environmental effects and the kinds of jobs that will actually be created. That conversation is most credible before final designs are fixed, when local evidence can still alter the investment rather than merely react to it." },
      { type: "paragraph", text: "The capital cycle will also test executive patience. New capacity often comes online after the conditions that justified it have changed. Leaders need governance that can distinguish temporary volatility from a broken premise. Cancelling too quickly wastes learning and relationships; continuing automatically converts commitment into escalation. Regular evidence-based reviews are the mechanism between those extremes." },
      { type: "bulletList", items: ["Prioritize assets that serve more than one strategic objective.", "Stage capacity so that demand evidence can shape later phases.", "Build regional supplier depth before a crisis requires it.", "Measure flexibility, recovery time and energy exposure alongside unit cost."] },
      { type: "heading", level: 2, text: "Growth With More Options" },
      { type: "paragraph", text: "The new cycle will not eliminate volatility. Its promise is more modest and more valuable: giving companies additional ways to respond. A flexible production line can change its mix. A regional supplier can cover a distant disruption. Better operational data can reveal a problem while there is still time to act." },
      { type: "paragraph", text: "Executives now face the difficult task of sustaining that logic when short-term pressure returns. Resilient systems can look inefficient in calm periods because their value lies in choices not yet exercised. The companies most likely to benefit will be those that treat investment not as a temporary reaction to disruption, but as the construction of a more adaptable foundation for growth." },
    ],
  },
  {
    articleId: "article-50-leaders",
    tags: [tag("Leadership"), tag("Innovation"), tag("Public Life"), tag("Next Generation")],
    relatedArticleIds: ["article-new-architecture-global-leadership", "article-professional-founder", "article-geography-entrepreneurship"],
    content: [
      { type: "paragraph", text: "The leaders who will shape the next decade do not fit a single portrait. They include founders translating scientific advances into useful systems, public officials rebuilding institutional capacity, investors extending the time available for difficult work and cultural figures changing which futures people can imagine." },
      { type: "paragraph", text: "What connects them is not celebrity or scale. It is leverage: the ability to alter how other people work, allocate resources or understand a problem. The Perspective's fictional 2026 leadership study looks beyond title and current valuation toward the institutions, practices and ideas likely to compound over time." },
      { type: "heading", level: 2, text: "How We Think About Influence" },
      { type: "paragraph", text: "Influence is easiest to measure after it becomes conventional. Our approach instead looks for people building the conditions from which broader change can emerge. Some lead large organizations. Others operate in smaller domains whose importance is only beginning to become visible. The aim is not a definitive ranking but a map of consequential work." },
      { type: "numberedList", items: ["Institutional effect: does the work outlast the individual decision?", "Practical originality: does a new idea change how something is actually done?", "Multiplier potential: does the leader expand the capability of others?", "Long-horizon relevance: will the underlying problem matter throughout the next decade?"] },
      { type: "heading", level: 2, text: "Builders of New Capacity" },
      { type: "paragraph", text: "A prominent group is building capacity that markets and governments once assumed would simply exist. They are creating energy systems for compute-intensive economies, new manufacturing platforms, clinical networks, climate-adaptation tools and institutions able to train people for changing work. Their contribution is often infrastructural and therefore easy to overlook until others depend on it." },
      { type: "pullQuote", quote: "The most durable leaders do more than make decisions. They leave behind a system that can make better decisions without them.", attribution: "The Perspective editors" },
      { type: "image", image: inlineImages.leadership, caption: "Leadership is increasingly measured by the capacity an institution creates for others.", credit: "Illustration for The Perspective." },
      { type: "paragraph", text: "These builders share a respect for implementation. They know that an ambitious goal becomes credible through procurement, maintenance, training and countless operating choices. Their organizations make room for technical experts and frontline evidence, resisting the tendency to turn complexity into a slogan." },
      { type: "paragraph", text: "They also understand that capacity is social as well as physical. A laboratory needs career paths that keep experienced researchers in the institution. A new energy system needs regulators able to evaluate unfamiliar designs. A manufacturing platform needs suppliers confident enough to invest alongside it. The leader's contribution is often the patient assembly of this surrounding system." },
      { type: "paragraph", text: "That work can be difficult to communicate because its milestones appear ordinary. A training cohort graduates, a permitting process becomes predictable, or a shared technical standard allows smaller organizations to participate. Yet these are the achievements that turn a one-time project into a platform for many projects, distributing capability beyond the original institution." },
      { type: "heading", level: 2, text: "Reformers of Established Institutions" },
      { type: "paragraph", text: "Another group works inside systems that cannot be replaced quickly: cities, universities, financial institutions and mature companies. Their task is renewal without interruption. They simplify rules that accumulated without intention, direct capital toward neglected capabilities and rebuild trust through visible competence." },
      { type: "callout", label: "Editorial perspective", text: "Leadership at scale is increasingly the work of renewal: preserving what remains useful while changing what prevents an institution from learning." },
      { type: "paragraph", text: "This work rarely produces a clean founding story. It demands coalition building, patience and the willingness to make progress legible to people with different interests. The best reformers understand that institutional memory can be both an asset and an obstacle. They honor the first while refusing to be governed by the second." },
      { type: "paragraph", text: "Their method is usually selective rather than theatrical. They identify the routines that protect quality, the rules that have lost their purpose and the informal relationships on which the formal system quietly depends. Reform succeeds when it removes friction without erasing the knowledge embedded in the institution's history." },
      { type: "paragraph", text: "This is why trust and measurement belong together. People need evidence that change is improving outcomes, but they also need confidence that metrics will not flatten the mission into whatever is easiest to count. The strongest reformers publish a small set of meaningful results and keep listening for consequences the dashboard cannot yet show." },
      { type: "heading", level: 2, text: "The Quiet Multipliers" },
      { type: "paragraph", text: "The final group changes fields through other people. They are teachers, editors, research leaders, early investors and community organizers whose judgment helps talent find direction. Their effect appears across many careers and organizations rather than under one name. In an era attracted to individual visibility, multiplier leadership remains profoundly undervalued." },
      { type: "paragraph", text: "Multipliers pay unusual attention to timing. They know when an emerging idea needs protection from premature judgment and when a promising person needs a demanding assignment rather than another credential. Their influence comes from combining standards with belief, giving people both an honest view of the work and a reason to imagine themselves capable of it." },
      { type: "paragraph", text: "Organizations can make this form of leadership less accidental. They can reward managers for talent that succeeds elsewhere, preserve time for teaching and recognize the people who connect specialists across boundaries. When advancement depends only on direct output or team retention, institutions discourage precisely the generosity through which knowledge and opportunity spread." },
      { type: "paragraph", text: "The people on this fictional list differ in field, geography and formal power, but they share that enlarging instinct. Their work leaves behind stronger teams, more capable systems and a wider range of people able to contribute. That is the standard by which influence becomes more than visibility." },
      { type: "paragraph", text: "Taken together, these leaders offer a wider definition of power. It includes the power to build, to repair, to connect and to make another person's contribution possible. The next decade will reward visible breakthroughs, but it will depend just as much on the patient creation of institutions capable of carrying those breakthroughs into ordinary life." },
    ],
  },
  {
    articleId: "article-family-businesses",
    tags: [tag("Family Business"), tag("Private Markets"), tag("Governance"), tag("Long-Term Capital")],
    relatedArticleIds: ["article-private-companies-scale", "article-purpose-capital", "article-investor-networks"],
    content: [
      { type: "paragraph", text: "Family-owned companies are attracting renewed investor attention as volatile markets increase the value of patient ownership. Their appeal is not nostalgia. In the strongest businesses, concentrated stewardship supports investment through cycles, preserves operating knowledge and allows strategy to develop beyond the timetable of quarterly expectations." },
      { type: "paragraph", text: "The category is broad, ranging from regional manufacturers to global consumer groups. Performance varies widely, and family control does not guarantee long-term thinking. Yet investors are finding that well-governed family enterprises can combine the focus of a founder-led company with the accumulated capability of an established institution." },
      { type: "heading", level: 2, text: "Patience Becomes an Operating Advantage" },
      { type: "paragraph", text: "Patient capital matters most when it changes operating choices. A company able to maintain apprenticeship programs during a downturn, preserve supplier relationships or fund a multi-year product transition may emerge stronger when demand returns. These decisions can reduce short-term margins while protecting capabilities that are expensive to rebuild." },
      { type: "pullQuote", quote: "The advantage is not that family owners ignore returns. It is that they can define the period over which a return should be understood.", attribution: "Julian Cross" },
      { type: "heading", level: 2, text: "Governance Determines the Difference" },
      { type: "paragraph", text: "Long horizons create value only when governance prevents them from becoming an excuse for weak accountability. Professional boards, clear family councils and transparent rules for leadership succession separate durable stewardship from personal control. The best systems make room for independent challenge while protecting a coherent purpose." },
      { type: "bulletList", items: ["Separate ownership rights from operating roles.", "Define how family and independent directors contribute to major decisions.", "Develop successors before a transition becomes urgent.", "Report performance in ways that make long-term commitments testable."] },
      { type: "image", image: inlineImages.growth, caption: "Long-horizon ownership can preserve operating capabilities through changing cycles.", credit: "Illustration for The Perspective." },
      { type: "paragraph", text: "Succession is the decisive test. A founder may hold product intuition, customer trust and informal authority that no job description captures. Transferring that influence requires more than naming a replacement. It requires turning tacit knowledge into institutional practice and giving the next generation room to lead differently." },
      { type: "paragraph", text: "Preparation often begins with exposure rather than appointment. Future owners learn the business through operating roles, outside experience and structured contact with employees and customers. Independent directors can help distinguish inherited confidence from demonstrated capability. The goal is not to reproduce the founder but to preserve the company's judgment while allowing its leadership style to evolve." },
      { type: "paragraph", text: "Ownership education matters as much as management development. Family members who will never work in the company still influence capital allocation, dividends and control. Clear information about risk, reinvestment and the obligations attached to ownership reduces the chance that strategic choices become proxies for unresolved family relationships." },
      { type: "heading", level: 2, text: "Why Outside Capital Is Interested" },
      { type: "paragraph", text: "Private investors see opportunities to support international expansion, digital systems and acquisitions without dismantling the ownership culture that made the business resilient. The most successful partnerships begin with explicit agreement about time horizon, leverage, reinvestment and the conditions under which control might change." },
      { type: "callout", label: "Investor lens", text: "A family company's governance quality matters more than the family label. Investors are underwriting decision systems as much as financial statements." },
      { type: "paragraph", text: "Tension is inevitable. Outside capital seeks visibility and defined outcomes; family owners may value independence and optionality. Productive tension can improve the company if both sides treat governance as a mechanism for surfacing trade-offs rather than as a ceremonial layer." },
      { type: "paragraph", text: "The structure of the investment should reflect those trade-offs. Excessive leverage can force a patient company into short decisions, while vague exit expectations can create conflict precisely when a difficult cycle requires unity. Thoughtful agreements establish what information will be shared, which decisions require consent and how either side can respond if the original assumptions change." },
      { type: "paragraph", text: "Investors are also learning to value operating continuity. Keeping a trusted plant manager, a multigenerational supplier relationship or a conservative balance-sheet practice may matter more than imposing a familiar playbook. The opportunity is to add capability without stripping away the accumulated knowledge that made the company attractive in the first place." },
      { type: "heading", level: 2, text: "Stewardship Must Keep Earning Its Place" },
      { type: "paragraph", text: "The renewed interest in family enterprise should not become a romantic story about permanence. Long ownership can preserve bad habits as easily as good ones. Durable companies periodically earn the right to remain durable by refreshing leadership, listening to outside evidence and investing before their current model is exhausted." },
      { type: "paragraph", text: "Renewal may require bringing in leaders with no family connection and giving them real authority. It may require closing a cherished operation, changing a dividend policy or entering a market the founding generation did not understand. A long horizon is valuable only when it creates room for necessary change rather than postponing it." },
      { type: "paragraph", text: "The healthiest owners treat stewardship as a temporary responsibility within a longer story. They document why major choices were made, invite the next generation to challenge inherited assumptions and define success in terms the business can test. That posture replaces entitlement with obligation and gives professional colleagues a clearer basis for trust." },
      { type: "paragraph", text: "It also makes partnership easier. Employees, lenders and minority investors can commit with greater confidence when continuity does not depend on private understandings they cannot see. The family remains an important source of purpose, but the institution becomes legible enough for others to help carry it forward." },
      { type: "paragraph", text: "That discipline explains the investor appeal. At their best, family businesses hold memory without becoming captive to it. They can connect generations of knowledge with professional management and patient capital. In markets defined by short reaction cycles, the ability to choose a longer horizon—and govern it responsibly—has become a scarce asset." },
    ],
  },
  {
    articleId: "article-opinion-productivity",
    tags: [tag("Opinion"), tag("Productivity"), tag("Technology"), tag("Work")],
    relatedArticleIds: ["article-human-machine", "article-ai-infrastructure", "article-professional-founder"],
    content: [
      { type: "paragraph", text: "Productivity may be entering a new golden age, but technology alone will not deliver it. The decisive variable is whether institutions redesign work around new capabilities or simply layer new tools onto old processes. History suggests that the largest gains arrive only after organizations change how decisions, responsibilities and expertise fit together." },
      { type: "paragraph", text: "The current AI cycle is following that pattern. Early adoption often makes individual tasks faster: drafting a document, reviewing code, finding a precedent or summarizing a meeting. Those gains are useful, but they remain local. Economy-wide productivity changes when faster tasks become different systems of work." },
      { type: "heading", level: 2, text: "Tools Do Not Redesign Institutions" },
      { type: "paragraph", text: "A company can give every employee an intelligent assistant and still preserve approvals that no longer add value, meetings that exist because information is fragmented and incentives that reward visible activity over useful outcomes. In that environment, automation may accelerate the production of work without improving the quality of the institution." },
      { type: "pullQuote", quote: "The productivity question is not how quickly a machine can complete yesterday's task. It is what people can build when yesterday's task no longer organizes the day.", attribution: "Ava Morgan" },
      { type: "paragraph", text: "Leaders therefore need to treat technology adoption as organizational design. They must decide which judgments remain human, which routine steps can disappear and where better information should change authority. This work is slower than licensing software, but it is the source of durable value." },
      { type: "heading", level: 2, text: "The Complementary Investments Matter" },
      { type: "paragraph", text: "New tools require complementary investment in training, data quality and management practice. Employees need time to learn where a system is reliable and where it requires scrutiny. Teams need shared standards for confidential information and accountable review. Managers need measures that capture better outcomes rather than simply higher output." },
      { type: "paragraph", text: "That learning cannot be confined to a launch workshop. People discover the real boundary of a tool only through repeated use in specific conditions. Organizations need forums where employees can compare failures, update guidance and remove applications that create more review than value. Adoption becomes productive when learning travels faster than mistakes repeat." },
      { type: "paragraph", text: "Managers must also resist using automation as a substitute for priorities. When every request becomes cheaper to produce, the volume of requests can expand until the organization is busier than before. The scarce resource remains attention. Good redesign removes low-value demand, clarifies which decisions matter and protects time for work whose quality cannot be improved by speed alone." },
      { type: "numberedList", items: ["Remove process steps made obsolete by better information.", "Train people to evaluate outputs, not merely generate them.", "Move authority when expertise and evidence move.", "Share productivity gains through better work, stronger wages or greater investment capacity."] },
      { type: "heading", level: 2, text: "A Wider Measure of Progress" },
      { type: "paragraph", text: "Productivity statistics are essential, but the lived quality of a productivity boom depends on distribution. If gains appear only as more intense work or concentrated returns, public confidence will weaken. If they allow smaller firms to access sophisticated capabilities, improve public services and give people more control over time, the benefits will be easier to sustain." },
      { type: "callout", label: "Opinion", text: "A genuine productivity era should be judged by the capacity it creates across society, not only by the volume of output it extracts from existing organizations." },
      { type: "paragraph", text: "This is also why competition matters. Broad access to capable tools can help new entrants challenge incumbents, but only if infrastructure, data and distribution do not become permanently closed. Policy should preserve room for experimentation while setting clear responsibility for harms." },
      { type: "paragraph", text: "Education will shape who can use that room. Technical literacy is important, but so are domain expertise, writing, quantitative judgment and the ability to frame a problem precisely. The most valuable workers may not be those who know the largest number of commands. They may be those who can connect a capable system to a real need and recognize when its answer is incomplete." },
      { type: "paragraph", text: "The gains should also create choices for workers. Some organizations will use productivity to shorten queues, raise quality or expand service; others may simply demand more output. Institutions that share the benefit through wages, learning, autonomy or time will build broader support for continued change. Productivity is politically durable when people can identify its dividend in their own lives." },
      { type: "heading", level: 2, text: "The Choice Inside the Forecast" },
      { type: "paragraph", text: "Forecasts often treat productivity as an external force that arrives through invention. In practice, productivity is built through thousands of institutional choices: whether to simplify a process, invest in a worker, share information or redesign a service around what is newly possible." },
      { type: "paragraph", text: "Those choices are easier when leaders begin with a real constraint rather than a fashionable tool. A hospital may need to reduce the time clinicians spend searching for records. A manufacturer may need faster diagnosis of equipment failure. A public agency may need to explain eligibility decisions consistently. Specific problems make it possible to compare improvement with risk." },
      { type: "paragraph", text: "They also keep accountability visible. When a system contributes to a decision, someone must remain responsible for the standard of that decision and able to explain how it was reached. Productivity that depends on unreviewable outputs will eventually be limited by mistrust. Reliable gains come from tools whose role is clear enough for people to challenge, correct and improve them." },
      { type: "paragraph", text: "That is a more demanding vision than effortless automation, but it is also a more hopeful one. It treats people not as residual costs around a machine, but as the source of purpose, judgment and improvement. Technology expands the frontier; institutions decide whether crossing it produces work and services worthy of the gain." },
      { type: "paragraph", text: "The technology is advancing quickly enough to create the opportunity. The harder work is ours. A golden age will not be defined by the intelligence embedded in machines, but by the intelligence with which organizations choose to use them." },
    ],
  },
  {
    articleId: "article-forces-global-economy",
    tags: [tag("Global Economy"), tag("Industrial Policy"), tag("Capital"), tag("Demographics")],
    relatedArticleIds: ["article-emerging-markets", "article-industrial-strategy", "article-purpose-capital"],
    content: [
      { type: "paragraph", text: "The global economy is being reshaped by forces that were once analyzed separately. Technology policy now influences capital allocation. Demographic change determines where labor is scarce and consumption expands. Energy security affects industrial competitiveness. Trade remains global, but the rules around strategic goods are becoming more regional and political." },
      { type: "paragraph", text: "No single trend explains the transition. The defining feature is convergence: several long-cycle changes are arriving at once, forcing companies and governments to make decisions before the new order is fully visible. The winners will not be those that predict every outcome, but those that build room to adapt." },
      { type: "heading", level: 2, text: "Capital Follows Strategic Capacity" },
      { type: "paragraph", text: "Investment is moving toward capabilities considered essential: compute, energy, advanced manufacturing, logistics and critical materials. Public incentives are influencing location decisions, but subsidies alone do not create durable clusters. Successful regions combine infrastructure with skills, supplier depth, research institutions and predictable rules." },
      { type: "paragraph", text: "This creates a more active relationship between state and market. Governments are trying to shape capacity without freezing competition; companies are accepting public support while navigating conditions attached to it. Both sides are relearning forms of coordination that had faded during the era of frictionless globalization." },
      { type: "paragraph", text: "Coordination does not eliminate competition. In well-designed programs, public investment establishes infrastructure or reduces early uncertainty while multiple firms still compete on execution. The danger appears when support protects a project from evidence, turning strategic importance into immunity from discipline. Capacity policy needs milestones, transparent costs and a willingness to change course." },
      { type: "paragraph", text: "Capital markets are adapting as well. Investors are separating short-lived demand spikes from assets that will remain useful across technologies and political cycles. They are asking whether a region can supply skilled labor, whether permitting is predictable and whether a project strengthens an ecosystem rather than depending indefinitely on exceptional support." },
      { type: "pullQuote", quote: "The new economic map will be drawn where capital, capability and public legitimacy can reinforce one another.", attribution: "David Owusu" },
      { type: "heading", level: 2, text: "Demography Changes the Equation" },
      { type: "paragraph", text: "Aging societies face tighter labor markets and rising demand for care, automation and productivity-enhancing investment. Younger societies need jobs, housing and infrastructure at a scale that tests institutional capacity. Migration can ease imbalances, but only where political systems and cities can integrate people credibly." },
      { type: "image", image: inlineImages.leadership, caption: "Economic strategy now brings capital, technology and public institutions into the same room.", credit: "Illustration for The Perspective." },
      { type: "paragraph", text: "Demography also changes consumer markets. Growth will come from different cities, household structures and age groups than it did in the previous cycle. Global companies must understand these shifts at a local level rather than treating emerging demand as a single category." },
      { type: "paragraph", text: "The institutional response will matter as much as the population curve. Two countries with similar age profiles can experience very different outcomes depending on housing supply, participation by women and older workers, childcare, health systems and the ability to adopt labor-saving technology. Demography creates pressure; policy and management determine how that pressure is absorbed." },
      { type: "heading", level: 2, text: "Technology Spreads Unevenly" },
      { type: "paragraph", text: "Artificial intelligence could offset labor constraints and expand access to expertise, but adoption will be uneven. Firms with clean data, modern infrastructure and managers able to redesign work will advance faster. Others may acquire tools without changing outcomes, widening the gap between frontier organizations and the rest." },
      { type: "paragraph", text: "Closing that gap requires diffusion, not merely invention. Smaller firms need interoperable tools, trusted advisers and financing for complementary investment. Public services need procurement systems that can test new approaches without committing entire institutions at once. The economic value of a general technology depends on how widely ordinary organizations learn to use it well." },
      { type: "bulletList", items: ["Industrial capacity is becoming a strategic asset again.", "Demographic divergence will reshape labor, demand and migration.", "Technology gains will depend on complementary institutional capability.", "Energy cost and reliability will influence the geography of growth."] },
      { type: "heading", level: 2, text: "An Economy of Strategic Choices" },
      { type: "paragraph", text: "The transition is often described as fragmentation, but that word can imply simple retreat. A more accurate description is selective connection. Countries and companies will remain deeply interdependent while making deliberate choices about where dependency is acceptable, where redundancy is valuable and which capabilities must remain close." },
      { type: "callout", label: "Premium analysis", text: "Resilience does not mean producing everything locally. It means understanding critical dependencies and preserving credible alternatives." },
      { type: "paragraph", text: "That distinction matters. Attempts at complete self-sufficiency would be costly and unrealistic. Strategic resilience instead requires visibility, diversified relationships and institutions capable of responding before a disruption becomes a crisis." },
      { type: "heading", level: 2, text: "The Long View" },
      { type: "paragraph", text: "The forces reshaping the economy will unfold over decades, but decisions made now will determine who develops the capacity to respond. Infrastructure, education and institutional trust compound slowly. They are difficult to improvise when conditions suddenly make them essential." },
      { type: "paragraph", text: "Long-horizon investment does not mean ignoring immediate affordability. Energy networks, housing, education and transport earn public support when people can see present benefit alongside future resilience. Sequencing matters: early projects should solve visible problems, build delivery capability and create evidence that makes the next commitment easier to trust." },
      { type: "paragraph", text: "Companies face a parallel obligation. Strategies framed around distant transformation must still guide today's capital budgets, supplier choices and talent development. The organizations that translate a ten-year view into a small number of current capabilities will learn sooner and preserve more options than those that alternate between grand forecasts and short-term reaction." },
      { type: "paragraph", text: "The central economic challenge is therefore not choosing between openness and resilience, technology and labor, or market and state. It is building arrangements in which these forces become mutually reinforcing. The next order will belong to societies and organizations able to connect long-term capacity with the discipline to keep adapting it." },
    ],
  },
];

function fallbackContent(article: Article): ArticleContentBlock[] {
  return [
    { type: "paragraph", text: `${article.excerpt} This story is part of The Perspective's fictional August 2026 editorial edition, examining the decisions, institutions and ideas shaping a changing global landscape.` },
    { type: "heading", level: 2, text: "Why This Matters" },
    { type: "paragraph", text: `The immediate development sits inside a larger ${article.category.name.toLowerCase()} story. Leaders are being asked to balance short-term evidence with capabilities that take years to build, while explaining those choices to employees, investors and the public.` },
    { type: "pullQuote", quote: "The most useful perspective connects today's decision with the system it will shape tomorrow.", attribution: "The Perspective newsroom" },
    { type: "heading", level: 2, text: "The Wider View" },
    { type: "paragraph", text: "The details will continue to evolve, but the underlying test is already clear: institutions need enough focus to act and enough flexibility to learn. That combination turns uncertainty from a reason to wait into a reason to build better options." },
  ];
}

function fallbackRelatedIds(article: Article) {
  return articles.filter((candidate) => candidate.id !== article.id && candidate.category.id === article.category.id).slice(0, 3).map((candidate) => candidate.id);
}

export function getArticleDetailBySlug(slug: string): ArticleDetail | undefined {
  const article = getArticleBySlug(slug);
  if (!article) return undefined;
  const detail = detailSeeds.find((candidate) => candidate.articleId === article.id);
  return { ...article, tags: detail?.tags ?? [tag(article.category.name), tag("The Perspective")], relatedArticleIds: detail?.relatedArticleIds ?? fallbackRelatedIds(article), content: detail?.content ?? fallbackContent(article) };
}

export function getRelatedArticles(article: Article, limit = 3) {
  const explicit = (article.relatedArticleIds ?? []).map(getArticleById).filter((candidate): candidate is Article => candidate !== undefined && candidate.id !== article.id);
  const sameCategory = articles.filter((candidate) => candidate.id !== article.id && candidate.category.id === article.category.id);
  const combined = [...explicit, ...sameCategory, ...articles.filter((candidate) => candidate.id !== article.id)];
  return combined.filter((candidate, index) => combined.findIndex((item) => item.id === candidate.id) === index).slice(0, limit);
}
